<script>
(function () {
  "use strict";

  /* ---------- Language mode ---------- */
  var buttons = document.querySelectorAll(".seg button");

  function setMode(mode) {
    if (["both", "en", "zh"].indexOf(mode) === -1) mode = "both";
    document.body.className = "mode-" + mode;
    buttons.forEach(function (b) {
      var active = b.dataset.mode === mode;
      b.classList.toggle("active", active);
      b.setAttribute("aria-pressed", String(active));
    });
    try { localStorage.setItem("sky-lang", mode); } catch (e) { /* ignore */ }
  }

  buttons.forEach(function (b) {
    b.addEventListener("click", function () { setMode(b.dataset.mode); });
  });

  var saved = null;
  try { saved = localStorage.getItem("sky-lang"); } catch (e) { /* ignore */ }
  setMode(saved || "both");

  /* Keyboard shortcuts: B = both, E = English, Z = Chinese */
  document.addEventListener("keydown", function (e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    var t = e.target;
    if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
    var k = e.key.toLowerCase();
    if (k === "b") setMode("both");
    else if (k === "e") setMode("en");
    else if (k === "z") setMode("zh");
  });

  /* ---------- Scroll-spy for section chips ---------- */
  var chips = Array.prototype.slice.call(document.querySelectorAll(".chip"));
  var byId = {};
  chips.forEach(function (c) {
    byId[c.getAttribute("href").slice(1)] = c;
  });

  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) {
          chips.forEach(function (c) { c.classList.remove("active"); });
          var chip = byId[en.target.id];
          if (chip) chip.classList.add("active");
        }
      });
    }, { rootMargin: "-35% 0px -55% 0px" });

    document.querySelectorAll("main section").forEach(function (s) { io.observe(s); });
  } else {
    /* Fallback: activate chip on click */
    chips.forEach(function (c) {
      c.addEventListener("click", function () {
        chips.forEach(function (x) { x.classList.remove("active"); });
        c.classList.add("active");
      });
    });
  }
})();
</script>

</body>
</html>
