Starry sky generation JS:
```js
function makeStars(container, n, minR, maxR) {
  var frag = document.createDocumentFragment();
  for (var i=0;i<n;i++){
    var s=document.createElement('i');
    s.style.left = (Math.random()*100)+'%';
    s.style.top = (Math.random()*100)+'%';
    var size = (minR + Math.random()*(maxR-minR));
    s.style.width = s.style.height = size.toFixed(2)+'px';
    s.style.animationDelay = (Math.random()*4).toFixed(2)+'s';
    s.style.animationDuration = (2.5 + Math.random()*3).toFixed(2)+'s';
    // some stars brighter
    s.style.opacity = (0.35 + Math.random()*0.65).toFixed(2);
    frag.appendChild(s);
  }
  container.appendChild(frag);
}
