    var t = e.target;
    if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
    var k = e.key.toLowerCase();
    if (k === "b") setMode("both");
    else if (k === "e") setMode("en");
    else if (k === "z") setMode("zh");
    else if (k === "t") setTheme(document.body.dataset.theme === "night" ? "day" : "night");
  });

  /* ---------- Theme: Day Mode / Night Mode ---------- */
  var themeBtn = document.getElementById("themeToggle");

  function setTheme(theme) {
    var isNight = theme === "night";
    document.body.dataset.theme = isNight ? "night" : "day";
    themeBtn.querySelector(".t-icon").textContent = isNight ? "☀️" : "🌙";
    themeBtn.querySelector(".t-label").textContent = isNight ? "Day Mode" : "Night Mode";
    themeBtn.setAttribute("aria-pressed", String(isNight));
    themeBtn.title = isNight ? "Switch to Day Mode" : "Switch to Night Mode";
    try { localStorage.setItem("sky-theme", isNight ? "night" : "day"); } catch (e2) { /* ignore */ }
  }

  themeBtn.addEventListener("click", function () {
    setTheme(document.body.dataset.theme === "night" ? "day" : "night");
  });

  var savedTheme = null;
  try { savedTheme = localStorage.getItem("sky-theme"); } catch (e3) { /* ignore */ }
  setTheme(savedTheme === "night" ? "night" : "day");

  /* ---------- Starfields (generated, no external assets) ---------- */
  function makeStars(id, count) {
    var box = document.getElementById(id);
    if (!box) return;
    var frag = document.createDocumentFragment();
    for (var i = 0; i < count; i++) {
      var s = document.createElement("i");
      var size = (0.8 + Math.random() * 1.8).toFixed(2);
      s.style.left = (Math.random() * 100).toFixed(2) + "%";
      s.style.top = (Math.random() * 100).toFixed(2) + "%";
      s.style.width = size + "px";
      s.style.height = size + "px";
      s.style.animationDelay = (Math.random() * 4).toFixed(2) + "s";
      s.style.animationDuration = (2.4 + Math.random() * 3.2).toFixed(2) + "s";
      frag.appendChild(s);
    }
    box.appendChild(frag);
  }
  makeStars("heroStars", 90);
  makeStars("bgStars", 150);"}]}

