import re
html = open('index.html', encoding='utf-8').read()

from html.parser import HTMLParser
class Checker(HTMLParser):
    VOID = {'meta','br','img','hr','input','link','source','path'}
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in self.VOID:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.VOID: return
        if not self.stack or self.stack[-1] != tag:
            self.errors.append(f"mismatch </{tag}> line {self.getpos()[0]}")
        else:
            self.stack.pop()
c = Checker()
c.feed(html)
print("html errors:", c.errors or "none")
print("unclosed:", c.stack or "none")

js = re.search(r'<script>(.*?)</script>', html, re.S).group(1)
open('/tmp/check.js','w').write(js)
EOF
node --check /tmp/check.js && echo "JS syntax OK"
