                <stop offset="0.92" stop-color="rgba(110,170,255,.30)"/>
                <stop offset="1" stop-color="rgba(110,170,255,0)"/>
              </radialGradient>
              <radialGradient id="ocean" cx="38%" cy="35%" r="80%">
                <stop offset="0" stop-color="#4f9fe0"/>
                <stop offset="1" stop-color="#1d5fa8"/>
              </radialGradient>
              <radialGradient id="mantleG" cx="50%" cy="50%" r="50%">
                <stop offset="0.35" stop-color="#f08a4d"/>
                <stop offset="0.75" stop-color="#c74a26"/>
                <stop offset="1" stop-color="#8f2f1d"/>
              </radialGradient>
              <radialGradient id="outerG" cx="50%" cy="50%" r="50%">
                <stop offset="0" stop-color="#ffd984"/>
                <stop offset="0.8" stop-color="#f0a13a"/>
                <stop offset="1" stop-color="#e08a26"/>
              </radialGradient>
              <radialGradient id="innerG" cx="45%" cy="42%" r="65%">
                <stop offset="0" stop-color="#fff6cf"/>
                <stop offset="1" stop-color="#f3cf6f"/>
              </radialGradient>
              <linearGradient id="crustG" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0" stop-color="#a98d5f"/>
                <stop offset="1" stop-color="#77603d"/>
              </linearGradient>
            </defs>

            <!-- الغلاف الجوي -->
            <circle cx="210" cy="210" r="196" fill="url(#atmo)"/>

            <!-- النصف الأيسر: السطح -->
            <g clip-path="url(#halfL)">
              <circle cx="210" cy="210" r="178" fill="url(#ocean)"/>
              <path d="M78 128 q30 -26 64 -14 q26 9 18 34 q-8 24 -36 26 q-34 2 -50 -18 q-12 -18 -6 -28 z" fill="#5d9e58" opacity=".95"/>
              <path d="M96 232 q28 -14 52 2 q18 13 8 34 q-10 22 -38 20 q-26 -2 -32 -22 q-4 -22 10 -34 z" fill="#5d9e58" opacity=".9"/>
              <ellipse cx="205" cy="42" rx="60" ry="14" fill="#eaf6ff" opacity=".8"/>
