            <dt>العمق</dt><dd id="pDepth">—</dd>
            <dt>الحرارة</dt><dd id="pTemp">—</dd>
            <dt>الحالة</dt><dd id="pState">—</dd>
            <dt>التركيب</dt><dd id="pComp">—</dd>
          </dl>
          <p id="panelDesc">—</p>
