  <!-- ================= الطبقات الأربع ================= -->
  <section id="layers" aria-labelledby="layers-title">
    <div class="sec-head">
      <span class="kicker">البنية</span>
      <h2 id="layers-title">الطبقات الأربع</h2>
      <p>كل طبقة لها سمكها وحرارتها وتكوينها؛ انقر أي بطاقة لعرضها في المقطع التفاعلي.</p>
    </div>
    <div class="lgrid">
      <article class="lcard" data-layer="crust" style="--lc: var(--c-crust)">
        <div class="lcard-top"><span class="dot"></span><h3>القشرة الأرضية</h3><span class="ldepth">0 – 70 كم</span></div>
        <dl>
          <dt>السُمك</dt><dd>5 – 70 كم</dd>
          <dt>الحرارة</dt><dd>25 – 400 °م</dd>
          <dt>الحالة</dt><dd>صلبة</dd>
          <dt>التكوين</dt><dd>سيليكات (جرانيت وبازلت)</dd>
        </dl>
        <p class="lnote">الطبقة الخارجية الرقيقة التي نعيش عليها؛ قارية (جرانيت) حتى 70 كم، ومحيطية (بازلت) بسُمك 5 – 10 كم فقط.</p>
      </article>

      <article class="lcard" data-layer="mantle" style="--lc: var(--c-mantle)">
        <div class="lcard-top"><span class="dot"></span><h3>الوشاح</h3><span class="ldepth">70 – 2,900 كم</span></div>
        <dl>
          <dt>السُمك</dt><dd>≈ 2,830 كم</dd>
          <dt>الحرارة</dt><dd>500 – 3,700 °م</dd>
          <dt>الحالة</dt><dd>صلب يتدفق ببطء</dd>
          <dt>التكوين</dt><dd>سيليكات غنية بالحديد والمغنيسيوم</dd>
        </dl>
        <p class="lnote">أكبر الطبقات حجمًا؛ صخره صلب يتدفق ببطء شديد في دورة حمل حراري تحرك الصفوح الصخرية.</p>
      </article>

      <article class="lcard" data-layer="outer" style="--lc: var(--c-outer)">
        <div class="lcard-top"><span class="dot"></span><h3>النواة الخارجية</h3><span class="ldepth">2,900 – 5,150 كم</span></div>
        <dl>
          <dt>السُمك</dt><dd>≈ 2,250 كم</dd>
          <dt>الحرارة</dt><dd>4,000 – 5,000 °م</dd>
          <dt>الحالة</dt><dd>سائلة (منصهرة)</dd>
          <dt>التكوين</dt><dd>حديد ونيكل وعناصر خفيفة</dd>
        </dl>
        <p class="lnote">طبقة سائلة من الحديد والنيكل؛ تدفقها يولّد عبر تأثير الدينامو المجال المغناطيسي للأرض.</p>
      </article>

      <article class="lcard" data-layer="inner" style="--lc: var(--c-inner)">
        <div class="lcard-top"><span class="dot"></span><h3>النواة الداخلية</h3><span class="ldepth">5,150 – 6,371 كم</span></div>
        <dl>
          <dt>السُمك</dt><dd>نصف قطر ≈ 1,220 كم</dd>
          <dt>الحرارة</dt><dd>≈ 5,500 °م</dd>
          <dt>الحالة</dt><dd>صلبة</dd>
          <dt>التكوين</dt><dd>حديد ونيكل تحت ضغط هائل</dd>
        </dl>
        <p class="lnote">كرة حديدية صلبة؛ الضغط الهائل عند المركز يبقيها صلبة رغم حرارة تقارب حرارة سطح الشمس.</p>
      </article>
    </div>
  </section>

  <!-- ================= استكشاف العمق ================= -->
  <section id="depth" aria-labelledby="depth-title">
    <div class="sec-head">
      <span class="kicker">رحلة إلى العمق</span>
      <h2 id="depth-title">استكشف الأرض كيلومترًا كيلومترًا</h2>
      <p>حرّك المؤشر لتُنزَّل من السطح نحو المركز، وشاهد كيف تتغير الطبقة والحرارة والحالة.</p>
    </div>
    <div class="card">
      <div class="depth-grid">
        <div class="depthbar" id="depthbar" aria-hidden="true">
          <div class="seg tiny" style="height:1.1%; --c:#8d7448"><i>القشرة</i></div>
          <div class="seg" style="height:44.4%; --c:#b23a22"><i>الوشاح</i></div>
          <div class="seg" style="height:35.3%; --c:#e88f2a"><i>النواة الخارجية</i></div>
          <div class="seg" style="height:19.2%; --c:#f3cf6f"><i>النواة الداخلية</i></div>
          <div class="marker" id="marker" style="top: 12.56%">
            <span class="m-label" id="mLabel">800 كم</span>
          </div>
        </div>

        <div class="depth-ui">
          <div class="slider-row">
            <label for="depthSlider" style="font-size:.85rem; color:var(--muted); font-weight:600;">عمقك الحالي داخل الأرض</label>
            <input type="range" id="depthSlider" min="0" max="6371" step="1" value="800">
            <div class="slider-labels"><span>السطح · 0 كم</span><span>مركز الأرض · 6,371 كم</span></div>
          </div>
          <div class="readout">
            <div class="ro-row"><span>العمق</span><strong id="roDepth">800 كم</strong></div>
            <div class="ro-row"><span>الطبقة</span><strong id="roLayer">—</strong></div>
            <div class="ro-row"><span>الحرارة التقديرية</span><strong id="roTemp">—</strong></div>
            <div class="ro-row"><span>الحالة</span><strong id="roState">—</strong></div>
            <div class="gauge" aria-hidden="true"><i id="gaugeFill" style="width: 26%"></i></div>
            <p class="depth-note">القيم التقريبية لأغراض تعليمية.</p>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- ================= العمليات الداخلية ================= -->
  <section id="processes" aria-labelledby="processes-title">
    <div class="sec-head">
      <span class="kicker">قوى خفية</span>
      <h2 id="processes-title">ماذا يجري داخل الأرض؟</h2>
      <p>الباطن الأرضي ليس ساكنًا: تيارات، مجالات، وموجات تعمل بلا توقف.</p>
    </div>
    <div class="pgrid">
      <div class="ptile">
        <svg viewBox="0 0 200 200" role="img" aria-label="حركة الحمل الحراري في الوشاح">
          <defs>
            <marker id="arrO" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6.5" markerHeight="6.5" orient="auto-start-reverse">
              <path d="M0 0 L10 5 L0 10 z" fill="#ffb066"/>
            </marker>
          </defs>
          <circle cx="100" cy="100" r="78" fill="none" stroke="rgba(255,255,255,.12)" stroke-width="30"/>
          <path class="conv-arrow" d="M 22 100 A 78 78 0 0 1 178 100" fill="none" stroke="#ffb066" stroke-width="5" marker-end="url(#arrO)"/>
          <path class="conv-arrow" d="M 178 100 A 78 78 0 0 1 22 100" fill="none" stroke="#ffb066" stroke-width="5" marker-end="url(#arrO)"/>
          <circle cx="100" cy="100" r="34" fill="#8f2f1d"/>
        </svg>
        <h3>الحمل الحراري</h3>
        <p>صخر الوشاح الصلاب يتدفق ببطء شديد بدفع الفرق الحراري بين النواة الحارة والسطح الأبرد؛ هذه الدورة المحرِكة الرئيسية لحركة الصفوح الزلزالية.</p>
      </div>

      <div class="ptile">
        <svg viewBox="0 0 220 200" role="img" aria-label="خطوط المجال المغناطيسي للأرض">
          <ellipse class="field-line" cx="110" cy="100" rx="80" ry="54" fill="none" stroke="#7db4ff" stroke-width="2" stroke-dasharray="10 8" opacity=".85"/>
          <ellipse class="field-line" cx="110" cy="100" rx="58" ry="38" fill="none" stroke="#7db4ff" stroke-width="2" stroke-dasharray="8 7" opacity=".65" style="animation-delay:.4s"/>
          <circle cx="110" cy="100" r="34" fill="#2a7fd4"/>
          <path d="M84 92 q14 -14 30 -6 q16 8 8 24 q-8 16 -26 12 q-18 -4 -16 -18 q2 -10 4 -12 z" fill="#5d9e58" opacity=".95"/>
          <line x1="110" y1="18" x2="110" y2="182" stroke="rgba(125,180,255,.5)" stroke-width="1.5" stroke-dasharray="3 5"/>
          <text x="110" y="13" text-anchor="middle" font-size="11" fill="#9fc6ff">الشمال المغناطيسي</text>
          <text x="110" y="197" text-anchor="middle" font-size="11" fill="#9fc6ff">الجنوب المغناطيسي</text>
        </svg>
        <h3>المجال المغناطيسي</h3>
        <p>تيارات الحديد المنصهر في النواة الخارجية تولّد مجالًا مغناطيسيًا يمتد ملايين الكيلومترات، يحمي الغلاف الجوي من تآكل الرياح الشمسية.</p>
      </div>

      <div class="ptile">
        <svg viewBox="0 0 200 200" role="img" aria-label="موجات زلزالية متسعة">
          <circle class="wave" cx="100" cy="100" r="42" fill="none" stroke="#ff9d6b" stroke-width="3" opacity=".55"/>
          <circle class="wave w2" cx="100" cy="100" r="42" fill="none" stroke="#ff9d6b" stroke-width="3" opacity=".55"/>
          <circle class="wave w3" cx="100" cy="100" r="42" fill="none" stroke="#ff9d6b" stroke-width="3" opacity=".55"/>
          <circle cx="100" cy="100" r="9" fill="#ff8d5a"/>
        </svg>
        <h3>الموجات الزلزالية</h3>
        <p>الموجات الأولية والثانوية هي «عدسة» باطن الأرض؛ توقف الموجات الثانوية عند النواة الخارجية بيّن أنها سائلة، وهو أساس كل ما نعرفه عن البنية الداخلية.</p>
      </div>
    </div>
  </section>

  <!-- ================= حقائق ================= -->
  <section id="facts" aria-labelledby="facts-title">
    <div class="sec-head">
      <span class="kicker">هل تعلم؟</span>
      <h2 id="facts-title">حقائق مدهشة عن باطن الأرض</h2>
    </div>
    <div class="fgrid">
      <div class="fact"><span class="emoji">🔥</span><p>حرارة مركز الأرض <b>≈ 5,500 °م</b> — تقارب حرارة سطح الشمس، وإن كانت أبرد بكثير من نواتها.</p></div>
      <div class="fact"><span class="emoji">🧱</span><p>الوشاح يشغل <b>~84%</b> من حجم الأرض، بينما القشرة التي نعيش عليها أقل من <b>1%</b>.</p></div>
      <div class="fact"><span class="emoji">🧊</span><p>النواة الداخلية <b>صلبة</b> رغم حرارة المنصهر؛ فالضغط المركزي (~360 غيغاباسكال) يمنع الانصهار.</p></div>
      <div class="fact"><span class="emoji">📡</span><p>الموجات الزلزالية هي «عدسة» باطن الأرض: الموجات الثانوية <b>S</b> لا تعبر السوائل، فبيّنت سائلية النواة الخارجية.</p></div>
      <div class="fact"><span class="emoji">🐌</span><p>تيارات الحمل في الوشاح تدفع الصفوح بمعدل <b>2 – 10 سم</b> سنويًا — أبطأ من نمو أظافرك.</p></div>
      <div class="fact"><span class="emoji">🛡️</span><p>الغلاف المغناطيسي يولّده الحديد المنصهر في النواة الخارجية، ويشكل <b>درعًا</b> يحمي الغلاف الجوي من التآكل بالرياح الشمسية.</p></div>
    </div>
  </section>
</main>

<footer>
  <p>أرقام تقريبية لأغراض تعليمية؛ سُمك القشرة في المخططات مبالغ فيه للوضوح.</p>
  <p>جميع الرسوم والألوان مدمجة داخل هذا الملف — دون أي موارد خارجية.</p>
</footer>

<script>
(function () {
  "use strict";

  /* ---------- بيانات الطبقات ---------- */
  var DATA = {
    crust: {
      name: "القشرة الأرضية",
      color: "var(--c-crust)",
      depth: "0 – 70 كم",
      temp: "25 – 400 °م",
      state: "صلبة",
      comp: "صخور سيليكاتية: جرانيت في القارات، وبازلت في قاع المحيطات",
      desc: "أرقّ طبقات الأرض وأكثرها برودة؛ نعيش على سطحها. القشرة القارية بسُمك حتى 70 كم، بينما قشرة المحيطات لا يزيد سُمكها عن 10 كم وهي أكثف. مع أعلى الوشاح تشكّل القشرة الصفيح الصخري المنقسم إلى صفوح."
    },
    mantle: {
      name: "الوشاح",
      color: "var(--c-mantle)",
      depth: "70 – 2,900 كم",
      temp: "500 – 3,700 °م",
      state: "صلب يتدفق ببطء شديد",
      comp: "سيليكات غنية بالحديد والمغنيسيوم",
      desc: "أكبر الطبقات حجمًا (~84% من حجم الأرض). صخره صلب لكنه يتحرك بحمل حراري على مدى ملايين السنين؛ طبقة الستينوسفير اللدنية في أعلاه تسمح بانزلاق الصفوح. حدوده السفلية مع النواة الخارجية هي حد غوتهبرغ."
    },
    outer: {
      name: "النواة الخارجية",
      color: "var(--c-outer)",
      depth: "2,900 – 5,150 كم",
      temp: "4,000 – 5,000 °م",
      state: "سائلة (منصهرة)",
      comp: "حديد ونيكل مع عناصر أخف كثافة",
      desc: "طبقة سائلة تدور فيها تيارات كهربائية تولّد، عبر تأثير الدينامو، المجال المغناطيسي للأرض الذي يحمينا من جسيمات الرياح الشمسية. اهتزازها الباطني (تذبذبات التنوية) قابل للرصد بأجهزة رصد الزلازل."
    },
    inner: {
      name: "النواة الداخلية",
      color: "var(--c-inner)",
      depth: "5,150 – 6,371 كم",
      temp: "≈ 5,500 °م",
      state: "صلبة",
      comp: "حديد ونيكل تحت ضغط ~360 غيغاباسكال",
      desc: "كرة صلبة نصف قطرها ~1,220 كم، حرارتها تقارب حرارة سطح الشمس، لكن الضغط الهائل عند مركز الأرض يمنع انصهارها. اكتُشفت عام 1936 من انكسار الموجات الزلزالية عند حد لييمان."
    }
  };

  var panel = document.getElementById("panel");

  function selectLayer(key) {
    var d = DATA[key];
    if (!d) return;
    document.getElementById("panelName").textContent = d.name;
    document.getElementById("pDepth").textContent = d.depth;
    document.getElementById("pTemp").textContent = d.temp;
    document.getElementById("pState").textContent = d.state;
    document.getElementById("pComp").textContent = d.comp;
    document.getElementById("panelDesc").textContent = d.desc;
    panel.style.setProperty("--pc", d.color);
    document.querySelectorAll(".lbtn").forEach(function (b) {
      b.classList.toggle("active", b.dataset.layer === key);
    });
    document.querySelectorAll(".halo").forEach(function (h) {
      h.classList.toggle("on", h.id === "H-" + key);
    });
  }

  /* توهج عند التمرير والتركيز */
  document.querySelectorAll(".layer").forEach(function (hit) {
    var key = hit.dataset.layer;
    function on() { document.getElementById("H-" + key).classList.add("on"); }
    function off() {
      document.querySelectorAll(".lbtn").forEach(function (b) {
        if (b.dataset.layer === key) document.getElementById("H-" + key).classList.toggle("on", b.classList.contains("active"));
      });
    }
    hit.addEventListener("mouseenter", on);
    hit.addEventListener("mouseleave", off);
    hit.addEventListener("focus", on);
    hit.addEventListener("blur", off);
    hit.addEventListener("click", function () { selectLayer(key); });
    hit.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); selectLayer(key); }
    });
  });

  document.querySelectorAll(".lbtn").forEach(function (b) {
    b.addEventListener("click", function () { selectLayer(b.dataset.layer); });
  });

  /* البطاقات: اختيار الطبقة والانتقال للمقطع */
  document.querySelectorAll(".lcard").forEach(function (card) {
    card.addEventListener("click", function () {
      selectLayer(card.dataset.layer);
      document.getElementById("map").scrollIntoView({ behavior: "smooth" });
    });
  });

  /* ---------- مستكشف العمق ---------- */
  var R_EARTH = 6371;

  function layerAt(d) {
    if (d < 70) return "crust";
    if (d < 2900) return "mantle";
    if (d < 5150) return "outer";
    return "inner";
  }

  function tempAt(d) {
    if (d <= 70) return 25 + (d / 70) * (400 - 25);
    if (d <= 2900) return 400 + ((d - 70) / (2900 - 70)) * (3700 - 400);
    if (d <= 5150) return 3700 + ((d - 2900) / (5150 - 2900)) * (4900 - 3700);
    return 4900 + ((d - 5150) / (R_EARTH - 5150)) * (5500 - 4900);
  }

  function fmt(n) {
    return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  }

  var slider = document.getElementById("depthSlider");
  var marker = document.getElementById("marker");

  function updateReadout() {
    var d = parseInt(slider.value, 10);
    var key = layerAt(d);
    var layer = DATA[key];
    var t = Math.round(tempAt(d) / 10) * 10;
    marker.style.top = (d / R_EARTH * 100) + "%";
    document.getElementById("mLabel").textContent = fmt(d) + " كم";
    document.getElementById("roDepth").textContent = fmt(d) + " كم";
    document.getElementById("roLayer").textContent = layer.name;
    document.getElementById("roTemp").textContent = "≈ " + fmt(t) + " °م";
    document.getElementById("roState").textContent = layer.state;
    document.getElementById("gaugeFill").style.width = Math.min(100, t / 5500 * 100) + "%";
  }

  slider.addEventListener("input", updateReadout);

  /* ---------- حقول النجوم ---------- */
  function makeStars(id, count) {
    var box = document.getElementById(id);
    if (!box) return;
    var frag = document.createDocumentFragment();
    for (var i = 0; i < count; i++) {
      var s = document.createElement("i");
      var size = (0.8 + Math.random() * 1.8).toFixed(2);
      s.style.left = (Math.random() * 100).toFixed(2) + "%";
      s.style.top = (Math.random() * 100).toFixed(2) + "%";
      s.style.width = size + "px";
      s.style.height = size + "px";
      s.style.animationDelay = (Math.random() * 4).toFixed(2) + "s";
      s.style.animationDuration = (2.4 + Math.random() * 3.2).toFixed(2) + "s";
      frag.appendChild(s);
    }
    box.appendChild(frag);
  }
  makeStars("heroStars", 100);
  makeStars("bgStars", 160);

  /* ---------- تعقب التمرير ---------- */
  var chips = Array.prototype.slice.call(document.querySelectorAll(".chip"));
  var byId = {};
  chips.forEach(function (c) { byId[c.getAttribute("href").slice(1)] = c; });

  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) {
          chips.forEach(function (c) { c.classList.remove("active"); });
          var chip = byId[en.target.id];
          if (chip) chip.classList.add("active");
        }
      });
    }, { rootMargin: "-35% 0px -55% 0px" });
    document.querySelectorAll("main section").forEach(function (s) { io.observe(s); });
  } else {
    chips.forEach(function (c) {
      c.addEventListener("click", function () {
        chips.forEach(function (x) { x.classList.remove("active"); });
        c.classList.add("active");
      });
    });
  }

  /* ---------- الحالة الأولية ---------- */
  selectLayer("mantle");
  updateReadout();
})();
</script>

