files = sorted(glob.glob('textures/*.png'))
cache = {}
for f in files:
    im = Image.open(f).convert('RGB').resize((256,256))
    a = np.asarray(im, dtype=np.float32)
    cache[f] = a

names = [os.path.basename(f) for f in files]
N = len(files)
# distance with option to flip G
def dist(i, j, flip):
    ai = cache[files[i]]; aj = cache[files[j]]
