cache = {}
for f in files:
    a = np.asarray(Image.open(f).convert('RGB').resize((512,512)), dtype=np.float32)
    cache[f] = (a[:,:,0], a[:,:,1])

names = {f: os.path.basename(f) for f in files}
N = len(files)

def twin_score(i, j):
    Ri, Gi = cache[files[i]]; Rj, Gj = cache[files[j]]
    # feature mask: where G deviates from background
    m = (np.abs(Gi-127) > 3) | (np.abs(Gj-127) > 3)
    if m.sum() < 500: return -1, -1
    rcorr = np.corrcoef(Ri[m].ravel(), Rj[m].ravel())[0,1]
    # G flip correlation
    gcorr_flip = np.corrcoef(Gi[m].ravel(), (255-Gj)[m].ravel())[0,1]
    gcorr_same = np.corrcoef(Gi[m].ravel(), Gj[m].ravel())[0,1]
    return rcorr, max(gcorr_flip, gcorr_same)

